func TestResolveEncodedBasePathJoin(t *testing.T) {
	// The upstream base path is sliced out of the raw configured URL and the
	// remainder is appended with exactly one slash at the junction. Encoded
	// slashes (both cases), the userinfo encoding, the IPv6 brackets and the
	// port are content that must survive byte for byte; only the run where
	// the base path's trailing slashes meet the remainder's leading slashes
	// collapses. None of these routes defines queryTransforms, so the raw
	// query is preserved verbatim.
	cfg := mustConfig(t, `{
	  "routes": [
	    {"id": "enc",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f///"},
	    {"id": "dots", "methods": ["GET"], "pathPrefix": "/d",   "upstream": "http://dots.internal/a/./b/../c//"},
	    {"id": "root", "methods": ["*"],   "pathPrefix": "/",    "upstream": "https://root.internal/v%2f//base%2f///"}
	  ]
	}`)

	cases := []struct {
		name     string
		request  string
		routeID  string
		upstream string
	}{
		{
			name:     "encoded base path, userinfo, IPv6 and port survive the join",
			request:  `{"method":"GET","target":"/api//%2F/x//y/?a=1&a=&flag"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/%2F/x//y/?a=1&a=&flag",
		},
		{
			name:     "exact prefix keeps the encoded base path and one junction slash",
			request:  `{"method":"GET","target":"/api"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/",
		},
		{
			name:     "exact prefix with empty query keeps the bare question mark",
			request:  `{"method":"GET","target":"/api?"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/?",
		},
		{
			name:     "no query string stays distinct from an empty one",
			request:  `{"method":"GET","target":"/api/x"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/x",
		},
		{
			name:     "duplicate, empty and valueless parameters stay as written",
			request:  `{"method":"GET","target":"/api/p?b=1&b=&flag&b=2&c=%2f"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/p?b=1&b=&flag&b=2&c=%2f",
		},
		{
			name:     "root prefix with root target keeps encoded base and junction slash",
			request:  `{"method":"GET","target":"/"}`,
			routeID:  "root",
			upstream: "https://root.internal/v%2f//base%2f/",
		},
		{
			name:     "dot segments in the base path are never resolved",
			request:  `{"method":"GET","target":"/d/x"}`,
			routeID:  "dots",
			upstream: "http://dots.internal/a/./b/../c/x",
		},
		{
			name:     "exact prefix on a dot-segment base keeps the trailing junction slash",
			request:  `{"method":"GET","target":"/d"}`,
			routeID:  "dots",
			upstream: "http://dots.internal/a/./b/../c/",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res := resolveJSON(t, cfg, tc.request)
			if res.RouteID != tc.routeID {
				t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
			}
			if res.UpstreamURL != tc.upstream {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
			}
		})
	}
}

func TestInvalidConfigBracketedHostMustBeIPv6(t *testing.T) {
	// Square brackets mark an IP literal: their content must be a legal IPv6
	// address. A plain name, a bare IPv4 address, an empty pair or a malformed
	// IPv6 literal rejects the whole configuration as invalid_config with a
	// content reason that locates the route by 1-based position, its id and
	// the upstream field — never as a broken JSON document. The offending
	// route is rejected even when an earlier route is the one a request hits.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"name in brackets", "http://[not-an-ip]/v1"},
		{"bare ipv4 in brackets", "http://[127.0.0.1]:8080/v1"},
		{"empty brackets", "http://[]/v1"},
		{"too many colons", "http://[2001:db8:::1]/v1"},
		{"non hex group", "http://[gggg::1]/v1"},
		{"missing closing bracket", "http://[::1/v1"},
		{"empty percent encoded zone", "http://[fe80::1%25]/v1"},
		{"future version literal is not plain ipv6", "http://[v1.fe80::]/v1"},
		{"bad escape in literal", "http://[fe80::1%zz]/v1"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			_, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "IPv6"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			if strings.Contains(f.Reason, "not valid JSON") {
				t.Fatalf("a bad bracketed host is a content error, not a JSON syntax failure: %q", f.Reason)
			}
		})
	}

	// A bracketed host on a later route rejects the config even though the
	// request only matches the first, valid route.
	cfg, f := ParseConfig([]byte(`{"routes":[
	  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
	  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"http://[not-an-ip]/v1"}
	]}`))
	if f == nil {
		t.Fatal("expected the later route's bracketed-name upstream to reject the config")
	}
	if cfg != nil {
		t.Fatalf("a rejected config must not be returned, got %+v", cfg)
	}
}

func TestInvalidConfigBracketedHostShape(t *testing.T) {
	// One pair of square brackets must wrap the whole host: after the
	// closing ']' only the optional port (":" plus digits) may follow before
	// the base path. A valid first literal never legitimizes a repeated
	// bracket group, a stray ']', text between the address and the port, or
	// non-port bytes — with or without userinfo. Every such upstream rejects
	// the whole configuration as invalid_config with a content reason naming
	// the route position, its id and the upstream field, never as broken
	// JSON.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"repeated bracket group", "http://[::1][::2]/v1"},
		{"text and a stray closing bracket", "http://[::1]extra]/v1"},
		{"stray closing bracket", "http://[::1]]/v1"},
		{"repeated bracket group before a port", "http://[::1][::2]:8080/v1"},
		{"repeated bracket group after a port", "http://[::1]:8080[::2]/v1"},
		{"bare text after the closing bracket", "http://[::1]extra/v1"},
		{"digits after the bracket without a colon", "http://[::1]8080/v1"},
		{"non digit bytes in the port", "http://[::1]:80a/v1"},
		{"extra colon group in the port", "http://[::1]:80:80/v1"},
		{"userinfo with a repeated bracket group", "http://user:pw@[::1][::2]/v1"},
		{"encoded userinfo with text and a stray bracket", "https://user:p%40ss@[::1]extra]/v1"},
		{"encoded userinfo with junk after the port", "https://user:p%40ss@[::1]:8443x/v1"},
		{"userinfo with a second bracket group after the port", "http://u@[::1]:8080[::2]/v1"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			cfg, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "bracketed host", "IPv6"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			if strings.Contains(f.Reason, "not valid JSON") {
				t.Fatalf("a bad bracketed host shape is a content error, not a JSON syntax failure: %q", f.Reason)
			}
			if cfg != nil {
				t.Fatalf("a rejected config must not be returned, got %+v", cfg)
			}
		})
	}

	// The offending route may be one the request never hits: config
	// validation still fails up front (and hands back no config at all)
	// instead of letting the first, valid route resolve the request.
	for _, up := range []string{"http://[::1][::2]/v1", "http://[::1]extra]/v1"} {
		src := `{"routes":[
		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
		  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + up + `"}
		]}`
		cfg, f := ParseConfig([]byte(src))
		if f == nil || f.Code != "invalid_config" {
			t.Fatalf("upstream %q: got %+v, want invalid_config", up, f)
		}
		if cfg != nil {
			t.Fatalf("upstream %q: a rejected config must not be returned", up)
		}
	}
}

func TestResolveValidIPv6Upstreams(t *testing.T) {
	// Full, compressed and IPv4-tail forms are legal, as are a port,
	// percent-encoded userinfo and a percent-encoded zone. Validation must
	// not re-encode or otherwise alter the configured bytes: joining slices
	// the raw upstream, so every legal spelling reaches upstreamURL byte for
	// byte.
	cases := []struct {
		name     string
		upstream string
		target   string
		want     string
	}{
		{
			name:     "full form",
			upstream: "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b",
			target:   "/x",
			want:     "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b/x",
		},
		{
			name:     "compressed form",
			upstream: "http://[2001:db8::1]/b",
			target:   "/x",
			want:     "http://[2001:db8::1]/b/x",
		},
		{
			name:     "embedded ipv4 tail with port",
			upstream: "http://[::ffff:192.168.0.1]:8080/b",
			target:   "/x",
			want:     "http://[::ffff:192.168.0.1]:8080/b/x",
		},
		{
			name:     "userinfo, port and encoded base path",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f",
			target:   "/api/orders?a=1&a=",
			want:     "https://user:p%40ss@[2001:db8::1]:8443/v%2f/orders?a=1&a=",
		},
		{
			name:     "percent encoded zone keeps its original spelling",
			upstream: "https://[fe80::1%25eth0]/base",
			target:   "/x?z=1",
			want:     "https://[fe80::1%25eth0]/base/x?z=1",
		},
		{
			name:     "uppercase hex groups",
			upstream: "http://[2001:DB8::ABCD]/b",
			target:   "/x",
			want:     "http://[2001:DB8::ABCD]/b/x",
		},
		{
			name:     "userinfo, port, encoded base path and encoded slash query all stay verbatim",
			upstream: "https://user:p%40ss@[2001:DB8::1]:8443/v%2f",
			target:   "/api/x?q=%2f",
			want:     "https://user:p%40ss@[2001:DB8::1]:8443/v%2f/x?q=%2f",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			prefix := "/"
			if strings.HasPrefix(tc.target, "/api") {
				prefix = "/api"
			}
			src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"` + prefix +
				`","upstream":"` + tc.upstream + `"}]}`
			cfg := mustConfig(t, src)
			res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
			if res.RouteID != "r" {
				t.Errorf("routeId = %q, want r", res.RouteID)
			}
			if res.UpstreamURL != tc.want {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.want)
			}
		})
	}
}

