// upstreamAddress is a raw upstream URL split at its address boundaries:
// the scheme prefix, the optional userinfo, the host (with any port), and
// the base path. All fields are slices of the original string — nothing is
// decoded, re-encoded or reordered — so validation and joining share one
// definition of where userinfo, host, port and base path begin and end.
type upstreamAddress struct {
    schemePrefix string // scheme and "://" separator; "" when hasScheme is false
    userinfo     string // userinfo including the trailing '@'; "" when absent
    hostPort     string // host with optional port, brackets included
    basePath     string // path from the first '/' after the authority; "" when absent
    hasScheme    bool
}

// splitUpstreamAddress cuts a raw upstream URL at its address boundaries.
// The authority starts after the "://" separator and ends at the first path
// slash (query and fragment are rejected by config validation before this
// runs); any userinfo precedes the host and ends at the last '@', so colons
// in userinfo or in the base path are never read as part of the host.
func splitUpstreamAddress(raw string) upstreamAddress {
    schemeEnd := strings.Index(raw, "://")
    if schemeEnd < 0 {
        return upstreamAddress{}
    }
    addr := upstreamAddress{schemePrefix: raw[:schemeEnd+3], hasScheme: true}
    rest := raw[schemeEnd+3:]
    authority := rest
    if i := strings.IndexByte(rest, '/'); i >= 0 {
        authority, addr.basePath = rest[:i], rest[i:]
    }
    hostPort := authority
    if i := strings.LastIndexByte(authority, '@'); i >= 0 {
        addr.userinfo = authority[:i+1]
        hostPort = authority[i+1:]
    }
    addr.hostPort = hostPort
    return addr
}
